    [4362]={name="Rough Boomstick",quality=2,ilvl=10,reqLevel=5,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering"},
    [4368]={name="Flying Tiger Goggles",quality=2,ilvl=20,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering"},
    [4369]={name="Deadly Blunderbuss",quality=2,ilvl=21,reqLevel=16,sourceType="profession",instructions="Crafted with Engineering (requires skill 1).",profession="Engineering"},
