    [5820]={name="Faerie Mantle",quality=2,ilvl=32,sourceType="quest_reward",instructions="Reward from the quest 'The Branch of Cenarius'. Pick it over the other reward choices. Starts with Anilia in Ashenvale. Objective: Kill Geltharis and return the Branch of Cenarius to Illiyana at the Shrine of Aessina.",zone="Ashenvale",questName="The Branch of Cenarius",lore="Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body."},
    [5957]={name="Handstitched Leather Vest",quality=2,ilvl=8,reqLevel=3,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5961]={name="Dark Leather Pants",quality=2,ilvl=23,reqLevel=18,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [5964]={name="Barbaric Shoulders",quality=2,ilvl=35,reqLevel=30,sourceType="profession",instructions="Crafted with Leatherworking (requires skill 1).",profession="Leatherworking"},
    [6085]={name="Footman Tunic",quality=2,ilvl=13,sourceType="quest_reward",instructions="Reward from the quest 'Wanted: \"Hogger\"'. Pick it over the other reward choices.",zone="Elwynn Forest",questName="Wanted:  \"Hogger\"",lore="Wanted: Hogger A huge gnoll, Hogger, is prowling the woods in southwestern Elwynn. He has overpowered all attempts at his capture. The Stormwind Army has placed a generous bounty on the Gnoll."},
    [6092]={name="Black Whelp Boots",quality=2,ilvl=18,sourceType="quest_reward",instructions="Reward from the quest 'Underbelly Scales'. Pick it over the other reward choices. Starts with Verner Osgood in Redridge Mountains. Objective: Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.",zone="Redridge Mountains",questName="Underbelly Scales",lore="I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire."},
