    [22477]={name="Bonescythe Legplates",quality=4,ilvl=88,reqLevel=60,sourceType="quest_reward",instructions="Reward from the quest 'Bonescythe Legplates'.",zone="Naxxramas",questName="Bonescythe Legplates",lore="If you want Bonescythe made, you're going to have to supply the materials."},
